/* ============================================
   নীহারিকা — University Club Website
   Minimal Botanical Aesthetic
   ============================================ */

/* --- TOKENS & RESET --- */
:root {
  --cream:        #FAF7F2;
  --cream-dark:   #F2EDE3;
  --cream-mid:    #EDE5D8;
  --brown-dark:   #3D2314;
  --brown-mid:    #6B3D22;
  --brown:        #8B5E3C;
  --brown-light:  #B88B6A;
  --brown-muted:  #C4A882;
  --text-primary: #2C1810;
  --text-body:    #4A3728;
  --text-muted:   #7A6055;
  --white:        #FFFFFF;

  --font-bengali: 'Hind Siliguri', 'Tiro Bangla', sans-serif;
  --font-serif:   'Tiro Bangla', 'Hind Siliguri', serif;

  --space-xs:  0.5rem;
  --space-sm:  1rem;
  --space-md:  1.5rem;
  --space-lg:  2.5rem;
  --space-xl:  4rem;
  --space-2xl: 6rem;

  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 16px;
  --radius-full: 9999px;

  --transition: 0.35s cubic-bezier(0.4, 0, 0.2, 1);
  --shadow-sm: 0 2px 8px rgba(60, 35, 20, 0.08);
  --shadow-md: 0 6px 24px rgba(60, 35, 20, 0.12);
  --shadow-lg: 0 16px 48px rgba(60, 35, 20, 0.18);

  --max-width: 1100px;
  --nav-h: 72px;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; font-size: 16px; }

body {
  font-family: var(--font-bengali);
  background-color: var(--cream);
  color: var(--text-body);
  line-height: 1.8;
  overflow-x: hidden;
}

img { max-width: 100%; display: block; }
a { text-decoration: none; color: inherit; }
ul { list-style: none; }
button { cursor: pointer; font-family: inherit; }
input, select, textarea { font-family: inherit; }

/* --- SCROLLBAR --- */
::-webkit-scrollbar { width: 6px; }
::-webkit-scrollbar-track { background: var(--cream-dark); }
::-webkit-scrollbar-thumb { background: var(--brown-light); border-radius: 3px; }


/* ============================================
   TYPOGRAPHY
   ============================================ */
h1, h2, h3, h4 {
  font-family: var(--font-serif);
  color: var(--text-primary);
  line-height: 1.35;
  font-weight: 400;
}

p { color: var(--text-body); }


/* ============================================
   CONTAINER
   ============================================ */
.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-md);
}


/* ============================================
   BUTTONS
   ============================================ */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.7rem 1.8rem;
  border-radius: var(--radius-full);
  font-size: 0.95rem;
  font-family: var(--font-bengali);
  font-weight: 500;
  border: 1.5px solid transparent;
  transition: var(--transition);
  white-space: nowrap;
}

.btn-primary {
  background: var(--brown);
  color: var(--cream);
  border-color: var(--brown);
}
.btn-primary:hover {
  background: var(--brown-dark);
  border-color: var(--brown-dark);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.btn-ghost {
  background: transparent;
  color: var(--brown);
  border-color: var(--brown);
}
.btn-ghost:hover {
  background: var(--brown);
  color: var(--cream);
  transform: translateY(-2px);
}

.btn-outline {
  background: transparent;
  color: var(--brown);
  border-color: var(--brown-light);
}
.btn-outline:hover {
  background: var(--cream-dark);
  border-color: var(--brown);
  transform: translateY(-2px);
}

.btn-sm { padding: 0.5rem 1.2rem; font-size: 0.85rem; }
.btn-full { width: 100%; justify-content: center; }


/* ============================================
   SECTION HEADER
   ============================================ */
.section {
  padding: var(--space-2xl) 0;
}

.section-header {
  text-align: center;
  margin-bottom: var(--space-xl);
}

.section-label {
  display: inline-block;
  font-size: 0.78rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--brown-light);
  margin-bottom: var(--space-xs);
  font-family: var(--font-bengali);
}

.section-title {
  font-size: clamp(1.8rem, 3vw, 2.6rem);
  color: var(--text-primary);
  margin-bottom: 0.8rem;
}

.section-divider {
  display: flex;
  justify-content: center;
  margin-top: 0.5rem;
}
.section-divider svg { width: 80px; opacity: 0.6; }

.section-cta {
  text-align: center;
  margin-top: var(--space-xl);
}


/* ============================================
   NAVIGATION
   ============================================ */
.site-header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  height: var(--nav-h);
  background: rgba(250, 247, 242, 0.85);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid transparent;
  transition: border-color var(--transition), box-shadow var(--transition);
}

.site-header.scrolled {
  border-bottom-color: var(--cream-mid);
  box-shadow: var(--shadow-sm);
}

.nav-container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-md);
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.nav-logo {
  display: flex;
  align-items: center;
  gap: 0.6rem;
}

.logo-img {
  height: 44px;
  width: auto;
}

.logo-text {
  font-family: var(--font-serif);
  font-size: 1.3rem;
  color: var(--brown-dark);
  font-weight: 400;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: var(--space-md);
}

.nav-link {
  font-size: 0.9rem;
  color: var(--text-body);
  position: relative;
  padding-bottom: 2px;
  transition: color var(--transition);
}
.nav-link::after {
  content: '';
  position: absolute;
  left: 0;
  bottom: 0;
  width: 0;
  height: 1px;
  background: var(--brown);
  transition: width var(--transition);
}
.nav-link:hover { color: var(--brown); }
.nav-link:hover::after { width: 100%; }

.nav-cta {
  background: var(--brown);
  color: var(--cream) !important;
  padding: 0.45rem 1.1rem;
  border-radius: var(--radius-full);
  border: 1.5px solid var(--brown);
  transition: var(--transition);
}
.nav-cta::after { display: none; }
.nav-cta:hover {
  background: var(--brown-dark);
  border-color: var(--brown-dark);
  transform: translateY(-1px);
}

/* Hamburger */
.nav-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  background: none;
  border: none;
  padding: 4px;
}
.nav-toggle span {
  display: block;
  width: 24px;
  height: 1.5px;
  background: var(--brown-dark);
  border-radius: 2px;
  transition: var(--transition);
}
.nav-toggle.active span:nth-child(1) { transform: translateY(6.5px) rotate(45deg); }
.nav-toggle.active span:nth-child(2) { opacity: 0; }
.nav-toggle.active span:nth-child(3) { transform: translateY(-6.5px) rotate(-45deg); }


/* ============================================
   HERO
   ============================================ */
.hero {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
  padding-top: var(--nav-h);
  background: var(--cream);
}

.hero-bg-pattern {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 70% 60% at 50% 30%, rgba(180, 130, 80, 0.06) 0%, transparent 70%),
    radial-gradient(ellipse 40% 40% at 20% 80%, rgba(139, 94, 60, 0.04) 0%, transparent 60%),
    radial-gradient(ellipse 40% 40% at 80% 70%, rgba(139, 94, 60, 0.04) 0%, transparent 60%);
  pointer-events: none;
}

.hero-botanical {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 220px;
  opacity: 0.18;
  pointer-events: none;
}
.hero-botanical-left { left: -40px; }
.hero-botanical-right { right: -40px; }

.hero-content {
  text-align: center;
  position: relative;
  z-index: 1;
  padding: var(--space-lg) var(--space-md);
  max-width: 700px;
}

.hero-tagline {
  font-size: 0.8rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--brown-light);
  margin-bottom: 1.2rem;
  opacity: 0;
  animation: fadeUp 0.8s 0.2s ease forwards;
}

.hero-title {
  font-family: var(--font-serif);
  font-size: clamp(3.5rem, 8vw, 6rem);
  color: var(--brown-dark);
  font-weight: 400;
  line-height: 1.1;
  margin-bottom: 1.5rem;
  opacity: 0;
  animation: fadeUp 0.8s 0.4s ease forwards;
}

.hero-description {
  font-size: clamp(0.95rem, 1.5vw, 1.1rem);
  color: var(--text-muted);
  line-height: 1.9;
  margin-bottom: var(--space-lg);
  opacity: 0;
  animation: fadeUp 0.8s 0.6s ease forwards;
}

.hero-actions {
  display: flex;
  gap: 1rem;
  justify-content: center;
  flex-wrap: wrap;
  opacity: 0;
  animation: fadeUp 0.8s 0.8s ease forwards;
}

.hero-scroll-indicator {
  position: absolute;
  bottom: 2rem;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.5rem;
  color: var(--brown-muted);
  font-size: 0.7rem;
  letter-spacing: 0.1em;
  opacity: 0;
  animation: fadeIn 1s 1.2s ease forwards;
}

.scroll-line {
  width: 1px;
  height: 40px;
  background: linear-gradient(to bottom, var(--brown-light), transparent);
  animation: scrollPulse 2s infinite;
}

@keyframes scrollPulse {
  0%, 100% { transform: scaleY(1); opacity: 1; }
  50% { transform: scaleY(0.6); opacity: 0.4; }
}

@keyframes fadeUp {
  from { opacity: 0; transform: translateY(24px); }
  to   { opacity: 1; transform: translateY(0); }
}

@keyframes fadeIn {
  from { opacity: 0; }
  to   { opacity: 1; }
}


/* ============================================
   ABOUT
   ============================================ */
.about {
  background: var(--cream-dark);
  position: relative;
  overflow: hidden;
}

.about::before {
  content: '';
  position: absolute;
  top: -2px;
  left: 0;
  right: 0;
  height: 3px;
  background: linear-gradient(to right, transparent, var(--brown-muted), transparent);
  opacity: 0.3;
}

.about-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-xl);
  align-items: start;
}

.about-text p {
  margin-bottom: 1rem;
  font-size: 0.97rem;
}

.about-lead {
  font-size: 1.15rem !important;
  color: var(--text-primary) !important;
  font-family: var(--font-serif);
  line-height: 1.7;
  margin-bottom: 1.4rem !important;
}

.about-stats {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
}

.stat-card {
  background: var(--cream);
  border: 1px solid var(--cream-mid);
  border-radius: var(--radius-lg);
  padding: 1.5rem 1rem;
  text-align: center;
  transition: var(--transition);
}
.stat-card:hover {
  border-color: var(--brown-light);
  box-shadow: var(--shadow-sm);
  transform: translateY(-4px);
}

.stat-number {
  display: block;
  font-family: var(--font-serif);
  font-size: 2rem;
  color: var(--brown);
  line-height: 1;
  margin-bottom: 0.3rem;
}

.stat-label {
  display: block;
  font-size: 0.8rem;
  color: var(--text-muted);
  letter-spacing: 0.05em;
}


/* ============================================
   NEWS
   ============================================ */
.news { background: var(--cream); }

.news-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  grid-template-rows: auto auto;
  gap: 1.2rem;
}

.news-card {
  background: var(--cream-dark);
  border: 1px solid var(--cream-mid);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: var(--transition);
  display: flex;
  flex-direction: column;
}
.news-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-4px);
  border-color: var(--brown-light);
}

.news-card-featured {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: 280px 1fr;
}

.news-card-img {
  overflow: hidden;
}

.news-img-placeholder {
  width: 100%;
  height: 100%;
  min-height: 200px;
  background: var(--cream-mid);
  display: flex;
  align-items: center;
  justify-content: center;
}

.placeholder-botanical svg {
  width: 80%;
  max-width: 160px;
  opacity: 0.5;
}

.news-card-body {
  padding: var(--space-md) var(--space-lg);
  flex: 1;
  display: flex;
  flex-direction: column;
}

.news-meta {
  display: flex;
  align-items: center;
  gap: 0.8rem;
  margin-bottom: 0.8rem;
}

.news-category {
  display: inline-block;
  font-size: 0.7rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--cream);
  background: var(--brown);
  padding: 0.2rem 0.7rem;
  border-radius: var(--radius-full);
}

.news-date {
  font-size: 0.8rem;
  color: var(--text-muted);
}

.news-title {
  font-size: 1.15rem;
  color: var(--text-primary);
  margin-bottom: 0.7rem;
  line-height: 1.5;
}
.news-card-featured .news-title { font-size: 1.4rem; }

.news-excerpt {
  font-size: 0.88rem;
  color: var(--text-muted);
  line-height: 1.75;
  flex: 1;
  margin-bottom: 1rem;
}

.news-read-more {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  font-size: 0.85rem;
  color: var(--brown);
  font-weight: 500;
  margin-top: auto;
  transition: var(--transition);
}
.news-read-more:hover { color: var(--brown-dark); gap: 0.7rem; }
.news-read-more .arrow { transition: var(--transition); }
.news-read-more:hover .arrow { transform: translateX(4px); }


/* ============================================
   INITIATIVES
   ============================================ */
.initiatives {
  background: var(--cream-dark);
  position: relative;
}

.initiatives-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.2rem;
}

.initiative-card {
  background: var(--cream);
  border: 1px solid var(--cream-mid);
  border-radius: var(--radius-lg);
  padding: var(--space-lg) var(--space-md);
  text-align: center;
  transition: var(--transition);
  position: relative;
  overflow: hidden;
}
.initiative-card::before {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 0;
  background: linear-gradient(to top, rgba(139,94,60,0.04), transparent);
  transition: height var(--transition);
}
.initiative-card:hover { 
  box-shadow: var(--shadow-md); 
  transform: translateY(-5px);
  border-color: var(--brown-light);
}
.initiative-card:hover::before { height: 60px; }

.initiative-icon {
  width: 56px;
  height: 56px;
  margin: 0 auto 1.2rem;
}
.initiative-icon svg { width: 100%; height: 100%; }

.initiative-title {
  font-size: 1.05rem;
  color: var(--text-primary);
  margin-bottom: 0.6rem;
}

.initiative-desc {
  font-size: 0.85rem;
  color: var(--text-muted);
  line-height: 1.75;
}


/* ============================================
   EVENTS
   ============================================ */
.events { background: var(--cream); }

.events-list {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.event-item {
  display: grid;
  grid-template-columns: 90px 1fr auto;
  gap: var(--space-md);
  align-items: center;
  background: var(--cream-dark);
  border: 1px solid var(--cream-mid);
  border-radius: var(--radius-lg);
  padding: var(--space-md) var(--space-lg);
  transition: var(--transition);
}
.event-item:hover {
  box-shadow: var(--shadow-md);
  transform: translateX(4px);
  border-color: var(--brown-light);
}

.event-date-block {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  background: var(--brown);
  color: var(--cream);
  border-radius: var(--radius-md);
  padding: 0.8rem 0.5rem;
  min-width: 70px;
}

.event-day {
  font-family: var(--font-serif);
  font-size: 1.8rem;
  line-height: 1;
}

.event-month {
  font-size: 0.72rem;
  letter-spacing: 0.08em;
  opacity: 0.85;
  margin-top: 0.2rem;
}

.event-details { flex: 1; }

.event-title {
  font-size: 1.05rem;
  color: var(--text-primary);
  margin-bottom: 0.4rem;
}

.event-meta {
  display: flex;
  gap: 1.2rem;
  flex-wrap: wrap;
  margin-bottom: 0.5rem;
}
.event-time, .event-location {
  font-size: 0.78rem;
  color: var(--text-muted);
}

.event-desc {
  font-size: 0.85rem;
  color: var(--text-muted);
  line-height: 1.7;
}


/* ============================================
   GALLERY STRIP
   ============================================ */
.gallery-strip {
  overflow: hidden;
  padding: var(--space-lg) 0;
  background: var(--cream-dark);
  border-top: 1px solid var(--cream-mid);
  border-bottom: 1px solid var(--cream-mid);
}

.gallery-track {
  display: flex;
  gap: 1rem;
  animation: galleryScroll 30s linear infinite;
  width: max-content;
}

.gallery-track:hover { animation-play-state: paused; }

.gallery-item {
  width: 240px;
  height: 160px;
  border-radius: var(--radius-md);
  flex-shrink: 0;
  background: var(--cream-mid);
  position: relative;
  overflow: hidden;
}

/* Subtle botanical pattern fills for gallery placeholders */
.g-item-1 { background: linear-gradient(135deg, #E8D9C5 0%, #D4BFA0 100%); }
.g-item-2 { background: linear-gradient(135deg, #D4C4B0 0%, #C0A882 100%); }
.g-item-3 { background: linear-gradient(135deg, #DCCFB8 0%, #C8AE8C 100%); }
.g-item-4 { background: linear-gradient(135deg, #E4D6C2 0%, #CCB694 100%); }
.g-item-5 { background: linear-gradient(135deg, #D8C9B2 0%, #C4A882 100%); }
.g-item-6 { background: linear-gradient(135deg, #E0D2BB 0%, #C9B390 100%); }

.gallery-item::after {
  content: '✿';
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2.5rem;
  opacity: 0.2;
  color: var(--brown-dark);
}

.g-item-2::after { content: '⊹'; font-size: 2rem; }
.g-item-3::after { content: '❧'; }
.g-item-4::after { content: '✦'; font-size: 2rem; }
.g-item-5::after { content: '⁂'; }
.g-item-6::after { content: '✾'; }

@keyframes galleryScroll {
  from { transform: translateX(0); }
  to   { transform: translateX(calc(-240px * 6 - 1rem * 6)); }
}


/* ============================================
   JOIN / CTA
   ============================================ */
.join {
  background: var(--cream);
  position: relative;
  overflow: hidden;
}

.join-bg-botanical {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: none;
}
.join-bg-botanical svg { width: 100%; max-width: 500px; opacity: 0.4; }

.join-content {
  position: relative;
  z-index: 1;
  max-width: 560px;
  margin: 0 auto;
  text-align: center;
}

.join-title {
  font-size: clamp(1.8rem, 3vw, 2.4rem);
  color: var(--text-primary);
  margin: 0.5rem 0 1rem;
}

.join-desc {
  color: var(--text-muted);
  font-size: 0.97rem;
  margin-bottom: var(--space-lg);
  line-height: 1.8;
}

.join-form {
  text-align: left;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.form-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.form-group label {
  font-size: 0.82rem;
  color: var(--text-muted);
  letter-spacing: 0.04em;
}

.form-group input,
.form-group select {
  padding: 0.7rem 1rem;
  border: 1.5px solid var(--cream-mid);
  border-radius: var(--radius-md);
  background: var(--cream-dark);
  color: var(--text-primary);
  font-size: 0.9rem;
  transition: border-color var(--transition), box-shadow var(--transition);
  outline: none;
  appearance: none;
  -webkit-appearance: none;
}

.form-group input:focus,
.form-group select:focus {
  border-color: var(--brown-light);
  box-shadow: 0 0 0 3px rgba(139,94,60,0.08);
}

.form-group input::placeholder { color: var(--brown-muted); opacity: 0.7; }

.join-success {
  display: none;
  text-align: center;
  padding: var(--space-lg);
  background: var(--cream-dark);
  border: 1px solid var(--cream-mid);
  border-radius: var(--radius-lg);
  margin-top: 1rem;
}

.join-success.visible { display: block; animation: fadeIn 0.4s ease; }
.success-icon { font-size: 2.5rem; margin-bottom: 0.5rem; color: var(--brown); }


/* ============================================
   FOOTER
   ============================================ */
.site-footer {
  background: var(--brown-dark);
  color: var(--cream-mid);
  padding: var(--space-xl) 0 var(--space-md);
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1.5fr 1fr;
  gap: var(--space-lg);
  padding-bottom: var(--space-xl);
  border-bottom: 1px solid rgba(196, 168, 130, 0.15);
}

.footer-logo {
  height: 48px;
  width: auto;
  filter: brightness(0) invert(1) opacity(0.7);
  margin-bottom: 1rem;
}

.footer-tagline {
  font-size: 0.88rem;
  color: var(--brown-muted);
  line-height: 1.8;
}

.footer-links-group h4 {
  color: var(--cream-mid);
  font-size: 0.85rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  margin-bottom: 1rem;
  font-family: var(--font-bengali);
  font-weight: 500;
}

.footer-links-group ul li {
  margin-bottom: 0.6rem;
  font-size: 0.85rem;
  color: var(--brown-muted);
}

.footer-links-group ul li a {
  color: var(--brown-muted);
  transition: color var(--transition);
}
.footer-links-group ul li a:hover { color: var(--cream); }

.footer-social h4 {
  color: var(--cream-mid);
  font-size: 0.85rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  margin-bottom: 1rem;
  font-family: var(--font-bengali);
  font-weight: 500;
}

.social-links {
  display: flex;
  gap: 0.8rem;
}

.social-link {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  border: 1px solid rgba(196, 168, 130, 0.2);
  border-radius: var(--radius-sm);
  color: var(--brown-muted);
  transition: var(--transition);
}
.social-link svg { width: 16px; height: 16px; }
.social-link:hover {
  border-color: var(--brown-light);
  color: var(--cream);
  background: rgba(196, 168, 130, 0.1);
  transform: translateY(-2px);
}

.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: var(--space-md);
  font-size: 0.78rem;
  color: rgba(196, 168, 130, 0.5);
}


/* ============================================
   REVEAL ANIMATIONS
   ============================================ */
.reveal {
  opacity: 0;
  transform: translateY(30px);
  transition: opacity 0.7s ease, transform 0.7s ease;
}
.reveal.visible {
  opacity: 1;
  transform: translateY(0);
}


/* ============================================
   RESPONSIVE
   ============================================ */
@media (max-width: 900px) {
  .about-grid { grid-template-columns: 1fr; }
  .initiatives-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: 1fr 1fr; gap: var(--space-md); }
}

@media (max-width: 768px) {
  .nav-links {
    position: fixed;
    top: var(--nav-h);
    left: 0;
    right: 0;
    background: rgba(250, 247, 242, 0.97);
    backdrop-filter: blur(12px);
    padding: var(--space-md);
    flex-direction: column;
    gap: 0;
    border-bottom: 1px solid var(--cream-mid);
    box-shadow: var(--shadow-md);
    transform: translateY(-110%);
    transition: transform var(--transition);
    z-index: 999;
  }
  .nav-links.open { transform: translateY(0); }
  .nav-links li { width: 100%; }
  .nav-link {
    display: block;
    padding: 0.9rem 0;
    border-bottom: 1px solid var(--cream-mid);
    font-size: 1rem;
  }
  .nav-cta { margin-top: 0.5rem; text-align: center; display: block; }
  .nav-toggle { display: flex; }

  .news-grid { grid-template-columns: 1fr; }
  .news-card-featured { grid-template-columns: 1fr; }
  .event-item { grid-template-columns: 70px 1fr; }
  .event-action { grid-column: 2; }
  .form-row { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .footer-bottom { flex-direction: column; gap: 0.5rem; text-align: center; }
  .hero-botanical { display: none; }
}

@media (max-width: 540px) {
  .initiatives-grid { grid-template-columns: 1fr; }
  .about-stats { grid-template-columns: 1fr 1fr; }
  .event-item { 
    grid-template-columns: 1fr;
    text-align: center;
  }
  .event-date-block {
    flex-direction: row;
    gap: 0.5rem;
    align-self: center;
    width: fit-content;
    margin: 0 auto;
  }
}

/* ============================================
   নীহারিকা JavaScript
   ============================================ */

(function () {
  'use strict';

  /* ---- NAV SCROLL EFFECT ---- */
  const header = document.getElementById('site-header');
  window.addEventListener('scroll', () => {
    header.classList.toggle('scrolled', window.scrollY > 20);
  }, { passive: true });


  /* ---- MOBILE NAV TOGGLE ---- */
  const navToggle = document.getElementById('nav-toggle');
  const navLinks  = document.getElementById('nav-links');

  navToggle.addEventListener('click', () => {
    const open = navLinks.classList.toggle('open');
    navToggle.classList.toggle('active', open);
    navToggle.setAttribute('aria-label', open ? 'মেনু বন্ধ করুন' : 'মেনু খুলুন');
  });

  // Close mobile menu on link click
  navLinks.querySelectorAll('.nav-link').forEach(link => {
    link.addEventListener('click', () => {
      navLinks.classList.remove('open');
      navToggle.classList.remove('active');
    });
  });


  /* ---- ACTIVE NAV LINK ON SCROLL ---- */
  const sections = document.querySelectorAll('section[id]');
  const navItems = document.querySelectorAll('.nav-link:not(.nav-cta)');

  const observerOptions = {
    root: null,
    rootMargin: '-40% 0px -55% 0px',
    threshold: 0,
  };

  const sectionObserver = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        navItems.forEach(link => {
          link.style.color = '';
          link.style.fontWeight = '';
        });
        const activeLink = document.querySelector(`.nav-link[href="#${entry.target.id}"]`);
        if (activeLink) {
          activeLink.style.color = 'var(--brown)';
          activeLink.style.fontWeight = '600';
        }
      }
    });
  }, observerOptions);

  sections.forEach(section => sectionObserver.observe(section));


  /* ---- REVEAL ON SCROLL ---- */
  const revealEls = document.querySelectorAll(
    '.news-card, .initiative-card, .event-item, .stat-card, .about-text, .about-stats, .section-header'
  );

  revealEls.forEach(el => el.classList.add('reveal'));

  const revealObserver = new IntersectionObserver((entries) => {
    entries.forEach((entry, i) => {
      if (entry.isIntersecting) {
        // Stagger within parent
        const siblings = Array.from(entry.target.parentElement.children);
        const idx = siblings.indexOf(entry.target);
        setTimeout(() => {
          entry.target.classList.add('visible');
        }, idx * 80);
        revealObserver.unobserve(entry.target);
      }
    });
  }, { rootMargin: '0px 0px -60px 0px', threshold: 0.1 });

  revealEls.forEach(el => revealObserver.observe(el));


  /* ---- COUNTER ANIMATION ---- */
  const statNumbers = document.querySelectorAll('.stat-number');
  const banglaDigits = ['০', '১', '২', '৩', '৪', '৫', '৬', '৭', '৮', '৯'];

  function toBangla(num) {
    return String(num).replace(/\d/g, d => banglaDigits[d]);
  }

  function animateCounter(el) {
    const rawText = el.textContent;
    const match   = rawText.match(/[\d]+/g);
    if (!match) return;

    const target   = parseInt(match[0]);
    const suffix   = rawText.replace(/[\d]+/, '').trim();
    const duration = 1600;
    const steps    = 50;
    const step     = duration / steps;
    let   current  = 0;

    const timer = setInterval(() => {
      current += target / steps;
      if (current >= target) {
        current = target;
        clearInterval(timer);
      }
      el.textContent = toBangla(Math.floor(current)) + suffix;
    }, step);
  }

  const counterObserver = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        animateCounter(entry.target);
        counterObserver.unobserve(entry.target);
      }
    });
  }, { threshold: 0.5 });

  statNumbers.forEach(el => counterObserver.observe(el));


  /* ---- JOIN FORM SUBMIT ---- */
  const joinForm    = document.getElementById('join-form');
  const joinSuccess = document.getElementById('join-success');

  if (joinForm) {
    joinForm.addEventListener('submit', (e) => {
      e.preventDefault();

      const name  = document.getElementById('fullname').value.trim();
      const email = document.getElementById('email').value.trim();

      if (!name || !email) {
        // Simple shake animation
        joinForm.style.animation = 'shake 0.4s ease';
        setTimeout(() => { joinForm.style.animation = ''; }, 400);
        return;
      }

      // Simulate send
      const submitBtn = document.getElementById('join-submit-btn');
      submitBtn.textContent = 'পাঠানো হচ্ছে...';
      submitBtn.disabled = true;

      setTimeout(() => {
        joinForm.style.display = 'none';
        joinSuccess.classList.add('visible');
      }, 1000);
    });
  }


  /* ---- SMOOTH PARALLAX ON HERO BOTANICAL ---- */
  const botLeft  = document.querySelector('.hero-botanical-left');
  const botRight = document.querySelector('.hero-botanical-right');

  if (botLeft && botRight) {
    window.addEventListener('scroll', () => {
      const y = window.scrollY * 0.15;
      botLeft.style.transform  = `translateY(calc(-50% + ${y}px))`;
      botRight.style.transform = `translateY(calc(-50% + ${y}px))`;
    }, { passive: true });
  }


  /* ---- CURSOR TRAIL (subtle) ---- */
  const trail = document.createElement('div');
  trail.style.cssText = `
    position:fixed; width:8px; height:8px;
    border-radius:50%; pointer-events:none; z-index:9999;
    background: rgba(139,94,60,0.35);
    transition: transform 0.1s ease, opacity 0.3s ease;
    opacity:0;
  `;
  document.body.appendChild(trail);

  let mouseX = 0, mouseY = 0, trailX = 0, trailY = 0;

  document.addEventListener('mousemove', (e) => {
    mouseX = e.clientX;
    mouseY = e.clientY;
    trail.style.opacity = '1';
  });

  document.addEventListener('mouseleave', () => { trail.style.opacity = '0'; });

  function animateTrail() {
    trailX += (mouseX - trailX) * 0.2;
    trailY += (mouseY - trailY) * 0.2;
    trail.style.left = (trailX - 4) + 'px';
    trail.style.top  = (trailY - 4) + 'px';
    requestAnimationFrame(animateTrail);
  }
  animateTrail();

})();

